<!doctype html><html lang="fr"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:12px;color:#172033}h1{text-align:center;color:#0f2744}.header{border-bottom:3px solid #167c80;padding-bottom:12px}.section{margin-top:18px}table{width:100%;border-collapse:collapse}td{padding:5px;border-bottom:1px solid #ddd}.sign{margin-top:55px;text-align:center}</style></head><body><div class="header"><h2>{{$entreprise->nom_entreprise}}</h2><div>{{$entreprise->adresse}} — {{$entreprise->telephone}}</div></div><h1>CONTRAT / ENGAGEMENT N° {{$contrat->numero}}</h1><div class="section"><h3>EMPLOYÉ</h3><table><tr><td>Matricule</td><td>{{$contrat->employe->matricule}}</td></tr><tr><td>Nom complet</td><td>{{$contrat->employe->nom}} {{$contrat->employe->postnom}} {{$contrat->employe->prenom}}</td></tr><tr><td>Adresse / téléphone</td><td>{{$contrat->employe->adresse}} — {{$contrat->employe->telephone}}</td></tr></table></div><div class="section"><h3>CONDITIONS</h3><table><tr><td>Type</td><td>{{$contrat->type}}</td></tr><tr><td>Période</td><td>{{$contrat->date_debut->format('d/m/Y')}} au {{$contrat->date_fin?->format('d/m/Y')??'indéterminée'}}</td></tr><tr><td>Poste</td><td>{{$contrat->poste??$contrat->fonction?->designation}}</td></tr><tr><td>Lieu</td><td>{{$contrat->lieu_travail}}</td></tr><tr><td>Rémunération</td><td>{{number_format($contrat->salaire_base,2,',',' ')}} {{$contrat->devise}} — {{$contrat->mode_remuneration}}</td></tr><tr><td>Primes / indemnités</td><td>{{number_format((float)$contrat->primes_fixes+(float)$contrat->indemnites_fixes,2,',',' ')}} {{$contrat->devise}}</td></tr><tr><td>Horaire</td><td>{{$contrat->heure_debut_prevue}} → {{$contrat->heure_fin_prevue}}</td></tr></table></div><div class="section"><h3>CONDITIONS PARTICULIÈRES</h3><p>{{$contrat->conditions_particulieres??$contrat->observations??'Néant'}}</p></div><table class="sign"><tr><td>L’EMPLOYEUR<br><br><br>Signature</td><td>L’EMPLOYÉ<br><br><br>Signature</td></tr></table></body></html>
